{"content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Gouraud-Shaded Rotating Cube</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #111; overflow: hidden; }
canvas { display: block; }
#info {
  position: absolute; top: 10px; left: 10px;
  color: #0f0; font: 14px monospace;
  background: rgba(0,0,0,0.5); padding: 8px 12px;
  border-radius: 4px; pointer-events: none;
}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="info">FPS: <span id="fps">0</span> | Wireframe: OFF | [W]oggle | [P]ause</div>
<script>
"use strict";

const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
const fpsEl = document.getElementById("fps");

let W, H;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
resize();
window.addEventListener("resize", resize);

// --- 3D Math ---
function vec3(x, y, z) { return [x, y, z]; }
function sub(a, b) { return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }
function cross(a, b) {
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
}
function dot(a, b) { return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; }
function normalize(v) {
  const l = Math.sqrt(dot(v,v)) || 1;
  return [v[0]/l, v[1]/l, v[2]/l];
}
function add(a, b) { return [a[0]+b[0], a[1]+b[1], a[2]+b[2]]; }
function scale(v, s) { return [v[0]*s, v[1]*s, v[2]*s]; }

// Rotation matrices
function rotX(a) {
  const c = Math.cos(a), s = Math.sin(a);
  return [[1,0,0],[0,c,-s],[0,s,c]];
}
function rotY(a) {
  const c = Math.cos(a), s = Math.sin(a);
  return [[c,0,s],[0,1,0],[-s,0,c]];
}
function rotZ(a) {
  const c = Math.cos(a), s = Math.sin(a);
  return [[c,-s,0],[s,c,0],[0,0,1]];
}

function matMulVec(m, v) {
  return [
    m[0][0]*v[0]+m[0][1]*v[1]+m[0][2]*v[2],
    m[1][0]*v[0]+m[1][1]*v[1]+m[1][2]*v[2],
    m[2][0]*v[0]+m[2][1]*v[1]+m[2][2]*v[2]
  ];
}

function matMulMat(a, b) {
  return [
    [a[0][0]*b[0][0]+a[0][1]*b[1][0]+a[0][2]*b[2][0],
     a[0][0]*b[0][1]+a[0][1]*b[1][1]+a[0][2]*b[2][1],
     a[0][0]*b[0][2]+a[0][1]*b[1][2]+a[0][2]*b[2][2]],
    [a[1][0]*b[0][0]+a[1][1]*b[1][0]+a[1][2]*b[2][0],
     a[1][0]*b[0][1]+a[1][1]*b[1][1]+a[1][2]*b[2][1],
     a[1][0]*b[0][2]+a[1][1]*b[1][2]+a[1][2]*b[2][2]],
    [a[2][0]*b[0][0]+a[2][1]*b[1][0]+a[2][2]*b[2][0],
     a[2][0]*b[0][1]+a[2][1]*b[1][1]+a[2][2]*b[2][1],
     a[2][0]*b[0][2]+a[2][1]*b[1][2]+a[2][2]*b[2][2]]
  ];
}

// --- Cube Definition ---
const SIZE = 120;
const vertices = [
  vec3(-SIZE, -SIZE, -SIZE), // 0
  vec3( SIZE, -SIZE, -SIZE), // 1
  vec3( SIZE,  SIZE, -SIZE), // 2
  vec3(-SIZE,  SIZE, -SIZE), // 3
  vec3(-SIZE, -SIZE,  SIZE), // 4
  vec3( SIZE, -SIZE,  SIZE), // 5
  vec3( SIZE,  SIZE,  SIZE), // 6
  vec3(-SIZE,  SIZE,  SIZE), // 7
];

// Faces defined as vertex index triples (already split into triangles)
const faces = [
  [0, 1, 2, 3], // front
  [4, 5, 6, 7], // back
  [0, 4, 7, 3], // left
  [1, 5, 6, 2], // right
  [0, 4, 5, 1], // bottom
  [3, 7, 6, 2], // top
];

// Base colors per face (RGB)
const faceColors = [
  [220, 60, 60],   // front - red
  [60, 220, 60],   // back - green
  [60, 60, 220],   // left - blue
  [220, 200, 60],  // right - yellow
  [220, 60, 220],  // bottom - magenta
  [60, 220, 220],  // top - cyan
];

// --- State ---
let angleX = 0, angleY = 0, angleZ = 0;
let showWireframe = false;
let paused = false;
let lastTime = performance.now();
let frameCount = 0;
let fps = 0;
let fpsTimer = 0;

// --- Light source (moving) ---
function getLightPos(time) {
  const t = time * 0.001;
  return [
    Math.sin(t * 0.7) * 250,
    Math.cos(t * 0.5) * 250,
    Math.sin(t * 0.3) * 200 + 200
  ];
}

// --- Render ---
function project(p, fov = 500) {
  const z = p[2] + 400; // camera offset
  const scale = fov / (z || 1);
  return [W / 2 + p[0] * scale, H / 2 - p[1] * scale, z];
}

function lambert(normal, lightDir) {
  const d = Math.max(0, dot(normal, lightDir));
  return 0.15 + 0.85 * d; // ambient + diffuse
}

function drawTriangle(p0, p1, p2, color, brightness) {
  const r = Math.min(255, color[0] * brightness);
  const g = Math.min(255, color[1] * brightness);
  const b = Math.min(255, color[2] * brightness);
  const fill = `rgb(${r|0},${g|0},${b|0})`;

  ctx.beginPath();
  ctx.moveTo(p0[0], p0[1]);
  ctx.lineTo(p1[0], p1[1]);
  ctx.lineTo(p2[0], p2[1]);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
}

function gouraudTriangle(v0, v1, v2, lightDir, baseColor, fov) {
  // Transform each vertex
  const t0 = v0.slice(), t1 = v1.slice(), t2 = v2.slice();

  // Compute per-vertex normals (face normal for flat faces)
  const n = normalize(cross(sub(v1, v0), sub(v2, v0)));

  // Light direction (normalized)
  const ld = normalize(lightDir);

  // Per-vertex brightness (Lambert)
  const b0 = lambert(n, ld);
  const b1 = lambert(n, ld);
  const b2 = lambert(n, ld);

  // Project vertices
  const p0 = project(t0, fov);
  const p1 = project(t1, fov);
  const p2 = project(t2, fov);

  // Gouraud: interpolate brightness across triangle
  const x0 = p0[0], y0 = p0[1];
  const x1 = p1[0], y1 = p1[1];
  const x2 = p2[0], y2 = p2[1];

  // Bounding box
  const minX = Math.max(0, Math.floor(Math.min(x0, x1, x2)));
  const maxX = Math.min(W - 1, Math.ceil(Math.max(x0, x1, x2)));
  const minY = Math.max(0, Math.floor(Math.min(y0, y1, y2)));
  const maxY = Math.min(H - 1, Math.ceil(Math.max(y0, y1, y2)));

  // Signed area * 2
  const area2 = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
  if (Math.abs(area2) < 0.001) return;

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.closePath();
  ctx.clip();

  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      // Barycentric coords
      const w0 = ((x1 - x2) * (y - y2) - (x - x2) * (y1 - y2)) / area2;
      const w1 = ((x2 - x0) * (y - y2) - (x - x2) * (y2 - y0)) / area2;
      const w2 = 1 - w0 - w1;

      if (w0 < -0.001 || w1 < -0.001 || w2 < -0.001) continue;

      const br = w0 * b0 + w1 * b1 + w2 * b2;
      const r = Math.min(255, baseColor[0] * br) | 0;
      const g = Math.min(255, baseColor[1] * br) | 0;
      const bl = Math.min(255, baseColor[2] * br) | 0;

      ctx.fillStyle = `rgb(${r},${g},${bl})`;
      ctx.fillRect(x, y, 1, 1);
    }
  }

  ctx.restore();
}

function render(time) {
  ctx.fillStyle = "#111";
  ctx.fillRect(0, 0, W, H);

  const lightPos = getLightPos(time);

  // Compute combined rotation matrix
  const mX = rotX(angleX);
  const mY = rotY(angleY);
  const mZ = rotZ(angleZ);
  const mRot = matMulMat(matMulMat(mX, mY), mZ);

  // Transform vertices
  const transformed = vertices.map(v => matMulVec(mRot, v));

  // Project
  const projected = transformed.map(v => project(v));

  // Build faces with normals and depth
  const renderList = [];

  for (let fi = 0; fi < faces.length; fi++) {
    const face = faces[fi];
    const v0 = transformed[face[0]];
    const v1 = transformed[face[1]];
    const v2 = transformed[face[2]];
    const v3 = transformed[face[3]];

    // Normal (using first triangle of quad)
    const n = normalize(cross(sub(v1, v0), sub(v3, v0)));

    // Backface culling
    const eyeDir = normalize(sub([0, 0, 0], [v0[0]+v1[0]+v2[0]+v3[0])/4, (v0[1]+v1[1]+v2[1]+v3[1])/4, (v0[2]+v1[2]+v2[2]+v3[2])/4]));
    // Simple: if normal.z > 0 (pointing toward camera), it's front-facing
    // But our camera looks along -z, so front-facing means normal.z < 0 after rotation
    // Actually: view direction is (0,0,1) from camera, so if dot(normal, view) > 0 => front
    const viewDir = [0, 0, 1];
    if (dot(n, viewDir) > 0) continue; // backface

    // Average depth for painter's algorithm
    const avgZ = (v0[2] + v1[2] + v2[2] + v3[2]) / 4;

    // Light direction from face center
    const center = [(v0[0]+v1[0]+v2[0]+v3[0])/4, (v0[1]+v1[1]+v2[1]+v3[1])/4, (v0[2]+v1[2]+v2[2]+v3[2])/4];
    const lightDir = normalize(sub(lightPos, center));

    renderList.push({
      face: face,
      transformed: [transformed[face[0]], transformed[face[1]], transformed[face[2]], transformed[face[3]]],
      projected: [projected[face[0]], projected[face[1]], projected[face[2]], projected[face[3]]],
      normal: n,
      depth: avgZ,
      color: faceColors[fi],
      lightDir: lightDir,
    });
  }

  // Sort back to front
  renderList.sort((a, b) => b.depth - a.depth);

  // Rasterize
  for (const f of renderList) {
    if (showWireframe) {
      const p = f.projected;
      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(p[0][0], p[0][1]);
      for (let i = 1; i < 4; i++) {
        ctx.lineTo(p[i][0], p[i][1]);
      }
      ctx.closePath();
      ctx.stroke();
    } else {
      // Split quad into 2 triangles
      gouraudTriangle(f.transformed[0], f.transformed[1], f.transformed[2], f.lightDir, f.color, 500);
      gouraudTriangle(f.transformed[0], f.transformed[2], f.transformed[3], f.lightDir, f.color, 500);
    }
  }
}

// --- Animation Loop ---
function animate(time) {
  requestAnimationFrame(animate);

  // FPS counter
  frameCount++;
  fpsTimer += time - lastTime;
  lastTime = time;
  if (fpsTimer >= 1000) {
    fps = Math.round(frameCount * 1000 / fpsTimer);
    fpsEl.textContent = fps;
    frameCount = 0;
    fpsTimer = 0;
  }

  if (!paused) {
    const dt = 1 / 60; // fixed timestep
    angleX += dt * 0.6;
    angleY += dt * 0.9;
    angleZ += dt * 0.3;
  }

  render(time);
}

// --- Input ---
window.addEventListener("keydown", (e) => {
  if (e.key === "w" || e.key === "W") {
    showWireframe = !showWireframe;
  }
  if (e.key === "p" || e.key === "P") {
    paused = !paused;
  }
});

// --- Start ---
requestAnimationFrame(animate);
</script>
</body>
</html>
